export function FlexContainer({
  direction = "{{direction}}",
  justify = "{{justify}}",
  align = "{{align}}",
  gap = {{gap}},
}) {
  const item = { background: "#A8E6C1", borderRadius: 6, width: 56, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700 };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="A flex container with four items, arranged by direction, justify-content and align-items">
      <div style={{ display: "flex", flexDirection: direction, justifyContent: justify, alignItems: align, gap,
        background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 12, minHeight: 120, boxSizing: "border-box" }}>
        <div style={{ ...item, height: 36 }}>1</div>
        <div style={{ ...item, height: 56 }}>2</div>
        <div style={{ ...item, height: 44 }}>3</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        direction: {direction} &middot; justify-content: {justify} &middot; align-items: {align} &middot; gap {gap}px
      </p>
    </div>
  );
}
